COPY (SELECT * FROM sirius_generate(
  num_batches := 3943,
  rows_per_batch := 8000000,
  seed := 42,
  columns := [
    {name: 'k', type: 'BIGINT', dist: 'uniform', p1: 0, p2: 1000000000000000},
    {name: 'v', type: 'DOUBLE', dist: 'uniform', p1: 0, p2: 1}
  ]
) ORDER BY k)
TO '/dev/null' (FORMAT sirius_discard)
